import {icon} from './icons.js';
export function createRadialMenu(canvas,{items,title,onOpen}){
 const root=document.createElement('div');root.className='radial-menu';root.hidden=true;root.setAttribute('role','menu');root.setAttribute('aria-label','Build actions');document.body.append(root);let down=null,previous=null;
 function close(){if(root.hidden)return;root.hidden=true;previous?.focus({preventScroll:true});}
 function open(x,y,event){onOpen(event);previous=document.activeElement;root.replaceChildren();const actions=items(),cx=Math.max(162,Math.min(innerWidth-162,x)),cy=Math.max(162,Math.min(innerHeight-162,y));root.style.left=cx+'px';root.style.top=cy+'px';
 const center=document.createElement('button');center.className='radial-center';center.innerHTML=icon('close');center.append(document.createTextNode(title()));center.setAttribute('aria-label','Close build actions');center.onclick=close;root.append(center);
 actions.forEach((a,i)=>{const angle=-Math.PI/2+i*Math.PI*2/actions.length,b=document.createElement('button');b.className='radial-action';b.setAttribute('role','menuitem');b.style.left=Math.cos(angle)*112+'px';b.style.top=Math.sin(angle)*112+'px';b.innerHTML=icon(a.icon);const label=document.createElement('span');label.textContent=a.label;b.append(label);if(a.key){const k=document.createElement('kbd');k.textContent=a.key;b.append(k);}b.disabled=!!a.disabled;b.onclick=()=>{close();a.run();};root.append(b);});root.hidden=false;root.querySelector('[role=menuitem]:not(:disabled)')?.focus();
 }
 canvas.addEventListener('contextmenu',e=>e.preventDefault());canvas.addEventListener('pointerdown',e=>{if(e.button===2)down={x:e.clientX,y:e.clientY};});canvas.addEventListener('pointerup',e=>{if(e.button!==2||!down)return;const clicked=Math.hypot(e.clientX-down.x,e.clientY-down.y)<5;down=null;if(clicked)open(e.clientX,e.clientY,e);});canvas.addEventListener('pointercancel',()=>down=null);
 canvas.addEventListener('keydown',e=>{if(e.key==='ContextMenu'||e.shiftKey&&e.key==='F10'){e.preventDefault();e.stopPropagation();const r=canvas.getBoundingClientRect();open(r.left+r.width/2,r.top+r.height/2,e);}});
 document.addEventListener('pointerdown',e=>{if(!root.hidden&&!root.contains(e.target))close();},true);
 document.addEventListener('keydown',e=>{if(root.hidden)return;if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();close();return;}if(['ArrowRight','ArrowDown','ArrowLeft','ArrowUp','Tab'].includes(e.key)){e.preventDefault();e.stopImmediatePropagation();const buttons=[...root.querySelectorAll('button:not(:disabled)')],n=buttons.indexOf(document.activeElement),delta=['ArrowLeft','ArrowUp'].includes(e.key)||e.shiftKey?-1:1;buttons[(n+delta+buttons.length)%buttons.length]?.focus();}},true);window.addEventListener('resize',close);return{close};
}
